size_t fn_19(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
  if (out_cap < len) {
    return -1;
  }

  for (size_t i = 0; i < len; i++) {
    uint8_t k = (arg >> (i * 8)) & 0xff;
    uint8_t r = (k >> (i % 8)) | (k << (8 - (i % 8)));
    out[i] = in[i] ^ r ^ i;
  }

  return len;
}
